    17	        String dbPassword = System.getenv("DB_PASSWORD");
    18	
    19	        if (dbUrl == null || dbUser == null || dbPassword == null) {
    20	            throw new RuntimeException("Database environment variables not set: DB_URL, DB_USER, DB_PASSWORD");
    21	        }
