    29	        config.setConnectionTimeout(20000);
    30	        config.setIdleTimeout(300000);
    31	        config.setMaxLifetime(1200000);
    32	
    33	        dataSource = new HikariDataSource(config);
    34	
    35	        try {
    36	            initializeSchema();
    37	        } catch (Exception e) {
    38	            throw new RuntimeException("Failed to initialize database schema", e);
    39	        }
    40	    }
    41	
    42	    public static Connection getConnection() {
    43	        if (dataSource == null) {
    44	            throw new RuntimeException("Database not initialized");
    45	        }
    46	        try {
    47	            return dataSource.getConnection();
    48	        } catch (Exception e) {
    49	            throw new RuntimeException("Failed to get database connection", e);
    50	        }
    51	    }
    52	
    53	    public static void close() {
