    55	            dataSource.close();
    56	        }
    57	    }
    58	
    59	    private static void initializeSchema() throws Exception {
    60	        try (InputStream is = Database.class.getResourceAsStream("/schema.sql");
    61	             BufferedReader reader = new BufferedReader(new InputStreamReader(is));
    62	             Connection conn = getConnection();
    63	             Statement stmt = conn.createStatement()) {
    64	
    65	            String line;
    66	            StringBuilder sql = new StringBuilder();
    67	            while ((line = reader.readLine()) != null) {
    68	                line = line.trim();
    69	                if (!line.isEmpty() && !line.startsWith("--")) {
    70	                    sql.append(line).append(" ");
    71	                    if (line.endsWith(";")) {
    72	                        stmt.execute(sql.toString());
    73	                        sql.setLength(0);
    74	                    }
    75	                }
    76	            }
    77	        }
    78	    }
    79	}
