     1	package com.pousada.service;
     2	
     3	import com.pousada.domain.Money;
     4	import com.pousada.domain.RatePlan;
     5	import com.pousada.domain.Room;
     6	import java.math.BigDecimal;
     7	import java.time.LocalDate;
     8	
     9	public class PricingService {
    10	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    11	    private static final int NON_REFUNDABLE_DISCOUNT_PERCENT = 15;
    12	
    13	    public static class PricingResult {
    14	        public final int nights;
    15	        public final BigDecimal subtotal;
    16	        public final BigDecimal discount;
    17	        public final BigDecimal total;
    18	
    19	        public PricingResult(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
    20	            this.nights = nights;
    21	            this.subtotal = subtotal;
    22	            this.discount = discount;
    23	            this.total = total;
    24	        }
    25	    }
    26	
    27	    public static PricingResult calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
    28	        int nights = calculateNights(checkIn, checkOut);
    29	        BigDecimal subtotal = BigDecimal.ZERO;
    30	
    31	        for (LocalDate date = checkIn; date.isBefore(checkOut); date = date.plusDays(1)) {
    32	            BigDecimal nightlyRate = room.nightlyRate;
    33	            if (SeasonalityCalculator.isHighSeason(date)) {
    34	                nightlyRate = Money.multiply(nightlyRate, HIGH_SEASON_MULTIPLIER);
    35	            }
    36	            subtotal = subtotal.add(nightlyRate);
    37	        }
    38	
    39	        subtotal = Money.round(subtotal);
    40	
    41	        BigDecimal discount = BigDecimal.ZERO;
    42	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
    43	            discount = Money.percent(subtotal, NON_REFUNDABLE_DISCOUNT_PERCENT);
    44	        }
    45	
    46	        BigDecimal total = Money.round(subtotal.subtract(discount));
    47	
    48	        return new PricingResult(nights, subtotal, discount, total);
    49	    }
    50	
    51	    private static int calculateNights(LocalDate checkIn, LocalDate checkOut) {
    52	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    53	    }
    54	}
