    12	    public static Reservation createReservation(int roomNumber, String guestName, String guestEmail,
    13	                                               String guestCpf, LocalDate checkIn, LocalDate checkOut,
    14	                                               int guests, RatePlan ratePlan) {
    15	        Room room = RoomRepository.findByNumber(roomNumber);
    16	        if (room == null) {
    17	            throw new ApiException("ROOM_NOT_FOUND", "Room not found", 404);
    18	        }
    19	
    20	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
    21	            throw new ApiException("INVALID_REQUEST", "Check-out must be after check-in", 400);
    22	        }
    23	
    24	        if (guests < 1) {
    25	            throw new ApiException("INVALID_REQUEST", "At least one guest is required", 400);
    26	        }
    27	
    28	        if (guests > room.capacity) {
    29	            throw new ApiException("CAPACITY_EXCEEDED", "Too many guests for this room", 422);
    30	        }
    31	
    32	        List<Reservation> conflicts = ReservationRepository.findByRoomAndDates(roomNumber, checkIn, checkOut);
    33	        if (!conflicts.isEmpty()) {
    34	            throw new ApiException("ROOM_UNAVAILABLE", "Room not available for these dates", 409);
    35	        }
    36	
    37	        PricingService.PricingResult pricing = PricingService.calculatePrice(room, checkIn, checkOut, ratePlan);
    38	
    39	        return ReservationRepository.create(
    40	                roomNumber, guestName, guestEmail, guestCpf,
    41	                checkIn, checkOut, guests, ratePlan,
    42	                pricing.nights, pricing.subtotal, pricing.discount, pricing.total
    43	        );
