    46	    public static Reservation confirmReservation(int id, BigDecimal amountPaid) {
    47	        Reservation reservation = ReservationRepository.findById(id);
    48	        if (reservation == null) {
    49	            throw new ApiException("RESERVATION_NOT_FOUND", "Reservation not found", 404);
    50	        }
    51	
    52	        if (reservation.status != ReservationStatus.PENDING) {
    53	            throw new ApiException("OPERATION_NOT_ALLOWED", "Can only confirm pending reservations", 409);
    54	        }
    55	
    56	        ReservationRepository.updateStatus(id, ReservationStatus.CONFIRMED);
    57	        ReservationRepository.updateAmountPaid(id, amountPaid);
    58	
