    66	    public static Reservation cancelReservation(int id) {
    67	        Reservation reservation = ReservationRepository.findById(id);
    68	        if (reservation == null) {
    69	            throw new ApiException("RESERVATION_NOT_FOUND", "Reservation not found", 404);
    70	        }
    71	
    72	        if (reservation.status != ReservationStatus.PENDING && reservation.status != ReservationStatus.CONFIRMED) {
    73	            throw new ApiException("OPERATION_NOT_ALLOWED", "Can only cancel pending or confirmed reservations", 409);
    74	        }
    75	
    76	        ReservationRepository.updateStatus(id, ReservationStatus.CANCELLED);
    77	
    78	        BigDecimal refund = BigDecimal.ZERO;
    79	        if (reservation.status == ReservationStatus.CONFIRMED) {
    80	            if (reservation.ratePlan == RatePlan.STANDARD) {
